def min_eating_speed(piles, h):
    """LC 875:二分『吃香蕉速度 k』。check(k) = 按速度 k 吃完所需小时数 <= h。
    速度越大耗时越少 → 可行性单调,求最小可行 k(最左 True)。"""
    def hours_needed(k):
        return sum((p + k - 1) // k for p in piles)   # 整数上取整,避免浮点丢精度
    lo, hi = 1, max(piles)                             # 速度至少 1,至多一次吃完最大堆
    while lo < hi:
        mid = (lo + hi) // 2                           # 求最左 True → 下取整
        if hours_needed(mid) <= h:                     # 可行,尝试更小的速度
            hi = mid
        else:
            lo = mid + 1
    return lo

def my_sqrt(x, eps=1e-7):
    """浮点二分求平方根:在 [0, max(x,1)] 上二分,使 mid*mid 逼近 x。
    答案是实数,用『区间宽度 < eps』作为终止条件。"""
    if x < 0:
        raise ValueError("x 必须非负")
    lo, hi = 0.0, max(x, 1.0)        # x<1 时 sqrt(x)>x,上界须取 max(x,1)
    while hi - lo > eps:
        mid = (lo + hi) / 2
        if mid * mid < x:            # 还偏小,真值在右半
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2

def max_distance(position, m):
    """LC 1552:把 m 个球放进货架,最大化相邻两球的最小间距 d。
    check(d) = 贪心能否放下 m 个(相邻间距 >= d);d 越大越难 → 求最大可行 d(最右 True)。"""
    pos = sorted(position)
    def can_place(d):
        count, last = 1, pos[0]
        for p in pos[1:]:
            if p - last >= d:
                count += 1
                last = p
        return count >= m
    lo, hi = 1, pos[-1] - pos[0]
    while lo < hi:
        mid = (lo + hi + 1) // 2      # 求最右 True → 必须上取整,否则死循环
        if can_place(mid):
            lo = mid                  # 可行,试更大的间距
        else:
            hi = mid - 1
    return lo

