import random
random.seed(1552)

assert max_distance([1, 2, 3, 4, 7], 3) == 3
assert max_distance([5, 4, 3, 2, 1, 1000000000], 2) == 999999999

def brute(position, m):
    pos = sorted(position)
    def can(d):
        count, last = 1, pos[0]
        for p in pos[1:]:
            if p - last >= d:
                count += 1
                last = p
        return count >= m
    best = 1
    for d in range(1, pos[-1] - pos[0] + 1):
        if can(d):
            best = d
    return best

for _ in range(300):
    n = random.randint(2, 8)
    pos = random.sample(range(0, 40), n)     # 互异坐标
    m = random.randint(2, n)
    assert max_distance(pos, m) == brute(pos, m), (pos, m)
